export function next(node, code) {
  let lo = starts[node], hi = starts[node+1];
  while (lo < hi) { const middle = lo+hi>>>1; if (labels.charCodeAt(middle) < code) lo = middle+1; else hi = middle; }
  return lo < starts[node+1] && labels.charCodeAt(lo) === code ? lo+1 : -1;
}
